//! Port of `test/compile/data/filter.test.ts`.
//!
//! The first upstream test checks the `ParseNode`s generated by
//! `parseTransformArray`; the parse layer is out of scope for this port.

use serde_json::json;
use vega_lite::compile::data::dataflow::{
    assemble, clone_node, dependent_fields, hash, parent, produced_fields,
    PlaceholderDataFlowNode,
};
use vega_lite::compile::data::filter::FilterNode;

#[test]
fn dependent_fields_and_produced_fields_return_the_right_fields() {
    let node = FilterNode::new(None, None, &json!("datum.foo > 2"));
    let deps: Vec<String> = dependent_fields(&node).into_iter().collect();
    assert_eq!(deps, vec!["foo".to_string()]);
    assert!(produced_fields(&node).unwrap().is_empty());
}

#[test]
fn hash_should_generate_the_correct_hash() {
    let filter_node = FilterNode::new(None, None, &json!({"field": "a", "equal": {"year": 2000}}));
    assert_eq!(
        hash(&filter_node),
        json!("Filter datum[\"a\"]===time(datetime(2000, 0, 1, 0, 0, 0, 0))")
    );
}

#[test]
fn clone_should_never_clone_parent() {
    let parent_node = PlaceholderDataFlowNode::new(None, "parent");
    let filter = FilterNode::new(Some(&parent_node), None, &json!("false"));
    assert!(parent(&clone_node(&filter)).is_none());
}

#[test]
fn assemble_converts_expr_in_predicates_correctly() {
    let node = FilterNode::new(None, None, &json!({"field": "foo", "equal": {"expr": "bar"}}));
    assert_eq!(assemble(&node)["expr"], json!("datum[\"foo\"]===bar"));
}

#[test]
fn supports_logical_composition() {
    let node = FilterNode::new(
        None,
        None,
        &json!({"and": [{"field": "a", "gt": 1}, {"field": "b", "lt": 2}]}),
    );
    assert_eq!(
        assemble(&node)["expr"],
        json!("(datum[\"a\"]>1) && (datum[\"b\"]<2)")
    );
    let mut deps: Vec<String> = dependent_fields(&node).into_iter().collect();
    deps.sort();
    assert_eq!(deps, vec!["a".to_string(), "b".to_string()]);
}
